  'Estas traps vêm de IPs que ainda não estão no inventário. Pede a um administrador para as rever e pré-registar o equipamento em Descoberta.': 'Diese Traps stammen von IPs, die noch nicht im Inventar sind. Bitten Sie einen Administrator, sie zu prüfen und das Gerät in der Discovery vorzuregistrieren.',
