  'SNMP → Traps de equipamentos desconhecidos': 'SNMP → Traps von unbekannten Geräten',
  'Para equipamentos SNMP, usa o separador SNMP. Pré-registar um equipamento é dizer à app, antes de ele estar no inventário, de que IP vão chegar as traps e com que credenciais. O pré-registo dura 24 horas e associa as traps que chegarem desse IP. Traps de IPs não pré-registados não se perdem:': 'Verwenden Sie für SNMP-Geräte den Tab SNMP. Durch die Vorregistrierung eines Geräts teilen Sie der Anwendung mit, bevor das Gerät im Inventar ist, von welcher IP und mit welchen Zugangsdaten seine Traps kommen. Die Vorregistrierung gilt 24 Stunden und verknüpft die von dieser IP eingehenden Traps. Traps von nicht vorregistrierten IPs gehen nicht verloren:',
